mapper.sql:
FROM flow_settlement fs


        AND fs.scope = #{query.scope}


        AND fs.trigger_type = #{query.triggerType}


        AND fs.user_id = #{query.userId}


        AND fs.tunnel_id = #{query.tunnelId}


        AND fs.user_tunnel_id = #{query.userTunnelId}


        AND (
            fs.user_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR fs.tunnel_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR fs.period_key LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND fs.settled_time >= #{query.startTime}


        AND fs.settled_time <= #{query.endTime}
